3	/**
4	 * Moves an issue between statuses and emits `issue.status_changed`.
5	 *
6	 * Owner D. The event is emitted by `IssueService`, not here — the notification
7	 * fan-out, the search reindex and the activity log all hang off that one event
8	 * rather than off this action.
9	 *
10	 * Must call (do not reimplement): changeIssueStatusSchema, can, getActor,
11	 * toActionResult
12	 */
13	
14	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
15	import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
16	import { withAction } from "@/actions/_lib/with-action";
17	import { CACHE_PROFILES, issueTag, projectTag, revalidateTagged } from "@/lib/cache";
18	import { can } from "@/lib/permissions";
19	import {
20	  changeIssueStatusSchema,
21	  type ChangeIssueStatusInput,
22	} from "@/schemas/issue";
23	import { changeIssueStatus } from "@/server/services/issue-service";
24	import type { ActionResult } from "@/types/api";
25	import type { Issue } from "@/types/issue";
26	
27	const run = withAction<typeof changeIssueStatusSchema, Issue>(
28	  changeIssueStatusSchema,
29	  async (raw, actor) => {
30	    const input = raw as ChangeIssueStatusInput;
31	
32	    const allowed = can(actor, "issue:update", {
33	      kind: "issue",
34	      orgId: input.orgId,
35	      projectId: PENDING_PROJECT_ID,
36	      issueId: input.issueId,
37	      authorId: actor.userId,
38	      assigneeId: actor.userId,
39	    });
40	    if (!allowed) {
41	      throw new ForbiddenActionError("issue:update");
42	    }
43	
44	    const issue = await changeIssueStatus(actor, input);
45	    revalidateTagged(
46	      [issueTag(issue.id), projectTag(issue.projectId)],
47	      CACHE_PROFILES.seconds,
48	    );
49	    return issue;
50	  },
51	  { revalidate: ["issues", "board"], cacheProfile: "seconds" },
52	);
53	
54	export async function changeIssueStatusAction(
55	  raw: unknown,
56	): Promise<ActionResult<Issue>> {
57	  return run(raw);
58	}
